import{processLayer1Optical}from"./moris-layer1-optical.js";import{extractDinov2Tokens,downsampleTo16x16Grid,computeHybridMaskedGemEmbedding,extractTopKeyPatches,executeGeometricGate,synthesizePerspectiveCentroid,rankStage2Candidates}from"./moris-layer2-embedding.js";import{computeEllipticFourierDescriptors,rerankLayer3Top10}from"./moris-layer3-rerank.js";import{saveSignature,saveSignaturesBatch,getAllSignatures,OFFLINE_PROFILE,isFreshSignature}from"./moris-idb.js";export async function enrollSkuSignature(skuId,rgba,width,height,extractor){const opt=processLayer1Optical(rgba,width,height);const rawModelOutput=await extractor(opt.pseudoRgbTensor,opt);const tokens=extractDinov2Tokens(rawModelOutput);const{mask16x16:mask16x16,edge16x16:edge16x16}=downsampleTo16x16Grid(opt.fgMask,opt.scharrEdgeMap,224,16);const canonicalEmbedding=computeHybridMaskedGemEmbedding(tokens.patchTokens,mask16x16,edge16x16);const perspectiveCentroid=synthesizePerspectiveCentroid(tokens.patchTokens,mask16x16,edge16x16);const keyPatches=extractTopKeyPatches(tokens.patchTokens,mask16x16,edge16x16,32);const efdCoefficients=computeEllipticFourierDescriptors(opt.outerContour,16);const signature={skuId:skuId,version:2,offlineProfile:OFFLINE_PROFILE,enrolledAt:Date.now(),aspectRatio:opt.aspectRatio,solidity:opt.solidity,holeCount:opt.holeCount,canonicalEmbedding:canonicalEmbedding,perspectiveCentroid:perspectiveCentroid,holeConstellation:opt.holeFeatures,efdCoefficients:efdCoefficients,keyPatches:keyPatches};await saveSignature(signature);return signature}export async function searchPartTop10(rgba,width,height,extractor,cachedCandidates){const opt=processLayer1Optical(rgba,width,height);const rawModelOutput=await extractor(opt.pseudoRgbTensor,opt);const tokens=extractDinov2Tokens(rawModelOutput);const{mask16x16:mask16x16,edge16x16:edge16x16}=downsampleTo16x16Grid(opt.fgMask,opt.scharrEdgeMap,224,16);const queryHybridVec=computeHybridMaskedGemEmbedding(tokens.patchTokens,mask16x16,edge16x16);const queryKeyPatches=extractTopKeyPatches(tokens.patchTokens,mask16x16,edge16x16,32);const queryEfd=computeEllipticFourierDescriptors(opt.outerContour,16);const candidatePool=cachedCandidates&&cachedCandidates.length>0?cachedCandidates.filter(sig=>isFreshSignature(sig)):await getAllSignatures();const gateResult=executeGeometricGate({aspectRatio:opt.aspectRatio,solidity:opt.solidity,holeCount:opt.holeCount},candidatePool);const stage2Ranked=rankStage2Candidates(queryHybridVec,gateResult.passed,40);const rerankInputs=stage2Ranked.top40.map(item=>({candidate:item.candidate,sHybridVec:item.score}));const top10=rerankLayer3Top10({keyPatches:queryKeyPatches,holeConstellation:opt.holeFeatures,efdCoefficients:queryEfd},rerankInputs,10);return{top10:top10,opticalDiagnostics:opt.diagnostics,totalCandidates:candidatePool.length,gatePassedCount:gateResult.passed.length}}export async function reindexBatchSignatures(items,extractor,onProgress){const errors=[];const signatures=[];const total=items.length;for(let i=0;i<total;i++){const item=items[i];try{const opt=processLayer1Optical(item.rgba,item.width,item.height);const rawModelOutput=await extractor(opt.pseudoRgbTensor,opt);const tokens=extractDinov2Tokens(rawModelOutput);const{mask16x16:mask16x16,edge16x16:edge16x16}=downsampleTo16x16Grid(opt.fgMask,opt.scharrEdgeMap,224,16);const canonicalEmbedding=computeHybridMaskedGemEmbedding(tokens.patchTokens,mask16x16,edge16x16);const perspectiveCentroid=synthesizePerspectiveCentroid(tokens.patchTokens,mask16x16,edge16x16);const keyPatches=extractTopKeyPatches(tokens.patchTokens,mask16x16,edge16x16,32);const efdCoefficients=computeEllipticFourierDescriptors(opt.outerContour,16);signatures.push({skuId:item.skuId,version:2,offlineProfile:OFFLINE_PROFILE,enrolledAt:Date.now(),aspectRatio:opt.aspectRatio,solidity:opt.solidity,holeCount:opt.holeCount,canonicalEmbedding:canonicalEmbedding,perspectiveCentroid:perspectiveCentroid,holeConstellation:opt.holeFeatures,efdCoefficients:efdCoefficients,keyPatches:keyPatches})}catch(err){errors.push({skuId:item.skuId,error:err?.message||String(err)})}onProgress?.(i+1,total)}if(signatures.length>0){await saveSignaturesBatch(signatures)}return{enrolled:signatures.length,errors:errors}}